WFJ.Data.add("spell", {
  [425012] = { "即座にオフハンド武器を投げて通常のオフハンド武器ダメージを与え、$N1%の確率でオフハンド武器の毒を対象に付与します。コンボポイントを$N2得ます。対象にかかっているDeadly Poison一回ごとにエネルギーを$N3返還します。\n\nPoisoned KnifeはSinister Strikeで発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0xefa7ed2e, nil, "um" },
  [425013] = { "即座にオフハンド武器を投げて通常のオフハンド武器ダメージを与え、$N1%の確率でオフハンド武器の毒を対象に付与します。コンボポイントを$N2得ます。\n\nPoisoned KnifeはSinister Strikeで発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0x2e09c327, nil, "um" },
  [425067] = { "ゴブリン流に重い門を開けます！", nil, 0x13dc7dbc, nil, "um" },
  [425094] = { "BrotherとSisterのHalf-Keysを組み合わせます。", nil, 0x1df3c5ff, nil, "um" },
  [425096] = { "ステルス中、およびステルスを解除してから6秒間の攻撃は、追加で$N2%のダメージを与えます。", nil, 0x94ffd5e1, nil, "um" },
  [425098] = { "ステルス中、およびステルスを解除してから6秒間の攻撃は、追加で$N2%のダメージを与えます。", "隠密中と、隠密解除後6秒間、与えるダメージが$N1%増加します。", 0x94ffd5e1, 0x5488e10f, "uu" },
  [425100] = { "Poisoned Knifeのアビリティを得ます：\n\n$I1\nオフハンド武器を即座に投げつけて通常のオフハンド武器ダメージを与え、100%の確率でオフハンド武器の毒を対象に付与します。コンボポイントを$N2獲得します。対象にかかっているDeadly Poisonの数ごとにエネルギーを$N3返還します。\n\nPoisoned Knifeは、Sinister Strikeから発動する、またはSinister Strikeを強化するすべての才能と効果の恩恵を受けます。", nil, 0x937b24a0, nil, "um" },
  [425101] = { "Master of Subtletyのアビリティを得ます：\n\n$I1\nステルス中、およびステルスを解除してから6秒間の攻撃は、追加で$N2%のダメージを与えます。", nil, 0xde540b32, nil, "um" },
  [425102] = { "ベルトにPoisoned Knifeのルーンを刻みます：\n\n$I1\nオフハンド武器を即座に投げて通常のオフハンド武器ダメージを与え、100%の確率でオフハンド武器の毒を対象に付与します。コンボポイントを$N2獲得します。対象に付与されたDeadly Poisonごとに、エネルギーを$N3返還します。\n\nPoisoned Knifeは、Sinister Strikeから発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0xdae3547b, nil, "um" },
  [425103] = { "ブーツにMaster of Subtletyのルーンを刻みます：\n\n$I1\n隠密中、および隠密を解除してから6秒間に行った攻撃のダメージが、さらに$N2%増加します。", nil, 0xb4456c3f, nil, "um" },
  [425121] = { "詠唱を加速させ、呪文の詠唱速度を$N1%上昇させ、詠唱中にダメージを伴う攻撃で受ける押し戻しを$N2%軽減します。効果時間は$D1です。", "すべての呪文の詠唱速度が$N1%上昇し、詠唱中にダメージ攻撃で受ける詠唱の遅れが$N2%減少しています。", 0xa582f7cd, 0xedaed79f, "uu" },
  [425124] = { "残りのマナをすべて解き放ち、エネルギーの奔流として対象に集中させ、$N1のArcaneダメージを与えます。このダメージは残りのマナに応じて最大$N2%増加します。その後、通常のマナ回復が再開され、$D1の間$N3%増加します。", "通常のマナ回復が有効になり、$N1%増加しています。", 0x339bcb87, 0xa28241d9, "uu" },
  [425168] = { "Arcane Surgeのアビリティを得ます：\n\n$I1\n残りのマナをすべてエネルギーの奔流として対象に解き放ち、$N1のArcaneダメージを与えます。このダメージは残りマナに応じて最大$N2%増加します。その後、通常のマナ回復が始まり、$D1の間$N3%増加します。", nil, 0x40f1c9b3, nil, "um" },
  [425169] = { "Icy Veinsのアビリティを得ます：\n\n$I1\n詠唱を速め、呪文の詠唱速度を$N1%上昇させ、詠唱中にダメージを伴う攻撃で受ける詠唱の遅延を$N2%減少させます。$D1持続します。", nil, 0xdad3711a, nil, "um" },
  [425170] = { "脚部にIcy Veinsのルーンを刻みます：\n\n$I1\n呪文の詠唱を加速し、詠唱速度を$N1%上昇させ、詠唱中にダメージを受けて生じる詠唱の遅延を$N2%軽減します。効果時間は$D1です。", nil, 0xe3b2f6e8, nil, "um" },
  [425171] = { "脚部にArcane Surgeのルーンを刻みます：\n\n$I1\n残りのマナをすべて解き放ち、エネルギーの奔流として対象に集中させ、$N1のArcaneダメージを与えます。このダメージは残りのマナに応じて最大$N2%増加します。その後、通常のマナ回復が有効になり、$D1の間$N3%増加します。", nil, 0x5e00b891, nil, "um" },
  [425198] = { "Mind FlayとMind Blastが、自分のShadow Word: Painにかかっている対象に与えるダメージが$N1%増加します。", nil, 0x7838fcf4, nil, "um" },
  [425204] = { "対象を病に冒し、$D1かけて$N1のShadowダメージを与えます。", "$N2秒ごとに$N1のダメージを与えます。", 0x6d5d1c3a, 0xa713b2d8, "uu" },
  [425205] = { nil, "受けるダメージが$N1%減少し、ダメージを受けても呪文の詠唱が遅れません。", nil, 0xc6bd28be, "mu" },
  [425207] = { "$D1の間、指定した場所に聖なる障壁を呼び出してパーティメンバー全員を守り、受けるすべてのダメージを$N2%軽減し、ダメージによる詠唱の遅延を防ぎます。", nil, 0xb1dd5c90, nil, "um" },
  [425210] = { "Twisted Faithのアビリティを得ます：\n\n$I1\nMind FlayとMind Blastが、自分のShadow Word: Painにかかっている対象に与えるダメージが$N1%増加します。", nil, 0xbe861b61, nil, "um" },
  [425211] = { "Void Plagueのアビリティを得ます：\n\n$I1\n対象を病気に冒し、$D1かけて$N1のShadowダメージを与えます。", nil, 0x19ef949a, nil, "um" },
  [425212] = { "Power Word: Barrierのアビリティを得ます：\n\n$I1\n聖なる障壁を呼び出し、$D1の間、対象地点にいるすべてのパーティーメンバーを守ります。受けるすべてのダメージを$N2%減少させ、ダメージによる詠唱の遅延を防ぎます。", nil, 0xba814dc9, nil, "um" },
  [425213] = { "手首にPower Word: Barrierのルーンを刻みます：\n\n$I1\n対象地点に聖なる障壁を$D1の間召喚してパーティーメンバー全員を守り、受けるダメージをすべて$N2%軽減し、ダメージによる詠唱の遅延を防ぎます。", nil, 0x192ed3ca, nil, "um" },
  [425215] = { "胸部か法衣にTwisted Faithのルーンを刻みます：\n\n$I1\nMind FlayとMind Blastが、自分のShadow Word: Painに冒されている対象に与えるダメージが$N1%増加します。", nil, 0x66bd1c0b, nil, "um" },
  [425216] = { "ブーツにVoid Plagueのルーンを刻みます：\n\n$I1\n対象を病気に冒し、$D1かけて$N1のShadowダメージを与えます。", nil, 0x42ee551e, nil, "um" },
  [425226] = { "燃えています！", "燃えています！", 0xfaec4c66, 0xfaec4c66, "uu" },
  [425233] = { "敵にShadowダメージを与えますが、大量の脅威を発生させます。", nil, 0xd6075571, nil, "um" },
  [425234] = { nil, "不安定な魔力がKelrisの周りに集まっています。\n\nShadowダメージが$N1%増加します。", nil, 0x65b78627, "mu" },
  [425235] = { nil, "スタンしていますが、ほとんど攻撃を受け付けません。", nil, 0x00b8f019, "mu" },
  [425239] = { nil, "移動速度が$N1%低下しています。\n$D1ごとにShadowダメージを受けます。", nil, 0xe5749210, "mu" },
  [425265] = { nil, "[PH] ツールチップが必要", nil, 0x1e8354d4, "mu" },
  [425266] = { "Renewが付与された直後にさらに一回回復するようになり、回復するたびに治癒ボーナス効果から受ける恩恵が$N1%増加します。\n\nさらに、他のPriestのRenewがかかっている対象にも自分のRenewを有効にできるようになります。", nil, 0x8faef343, nil, "um" },
  [425268] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425269] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425270] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425271] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425272] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425273] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425274] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425275] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425276] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425277] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425280] = { "Flash Heal、Binding Heal、Lesser Heal、Heal、Greater Heal、Penanceによる回復は、Weakened Soulがかかっている対象に唱えるとクリティカル率が$N1%上昇し、対象のWeakened Soulの残り効果時間を$N2秒短縮します。", nil, 0x1cb93a0f, nil, "um" },
  [425284] = { "使用すると、$D1の間Spirit of Redemptionになります。この形態の間は、あらゆる治癒呪文をコストなしで詠唱できますが、移動、攻撃ができず、攻撃されず、呪文や効果の対象にもなりません。使用にはSpirit of Redemptionの才能が必要で、死亡時にSpirit of Redemptionにならなくなります。", "誰にも想像できないほどの力を得ました。", 0xbb79c036, 0x393ecc0c, "uu" },
  [425285] = { "エレメントの霊たちに呼びかけます。", nil, 0x091afdbb, nil, "um" },
  [425294] = { "純粋なShadowエネルギーに分散し、受けるすべてのダメージを$N1%軽減します。攻撃や呪文の詠唱はできませんが、$D2の間、$N3秒ごとにマナを$N2%回復します。Dispersionはスタン、恐怖、沈黙状態でも使用でき、使用時にすべての移動速度低下効果と移動妨害効果を解除し、分散している間はそれらに対して無効になります。", "受けるすべてのダメージが$N1%軽減され、$D2の間、$N3秒ごとにマナを$N2%回復しています。攻撃や呪文の詠唱はできません。移動速度低下効果と移動妨害効果に対して無効です。", 0xf9ae902a, 0xa58e8279, "uu" },
  [425302] = { "Empowered Renewのアビリティを得ます：\n\n$I1\nRenewが付与された直後にさらに一回回復するようになり、回復するたびに治癒ボーナス効果から受ける恩恵が$N1%増加します。\n\nさらに、他のPriestのRenewがかかっている対象にも自分のRenewを有効にできるようになります。", nil, 0x6f1dc8a5, nil, "um" },
  [425303] = { "Renewed Hopeのアビリティを得ます：\n\n$I1\nFlash Heal、Binding Heal、Lesser Heal、Heal、Greater Heal、Penanceによる回復は、Weakened Soulのかかった対象に詠唱するとクリティカル率が$N1%上昇し、対象のWeakened Soulの残り時間を$D1短縮します。", nil, 0xdf0b8af4, nil, "um" },
  [425304] = { "Spirit of the Redeemerのアビリティを得ます：\n\n$I1\n使用すると、$D1の間Spirit of Redemptionになります。この形態の間は、あらゆる治癒呪文をコストなしで詠唱できますが、移動、攻撃ができず、攻撃されず、呪文や効果の対象にもなりません。使用にはSpirit of Redemptionの才能が必要で、死亡時にSpirit of Redemptionにならなくなります。", nil, 0xcd4dc4ca, nil, "um" },
  [425307] = { "Dispersionのアビリティを得ます：\n\n$I1\n純粋なShadowのエネルギーに分散し、受けるすべてのダメージを$N1%減少させます。攻撃も呪文の詠唱もできなくなりますが、$D2の間、$D1ごとにマナを$N2%回復します。Dispersionはスタン、恐怖、沈黙状態でも詠唱でき、詠唱時にすべての移動阻害効果を解除し、分散している間はそれらを無効化します。", nil, 0x23f83f06, nil, "um" },
  [425309] = { "ベルトにEmpowered Renewのルーンを刻みます：\n\n$I1\nRenewが、付与された時に即座に一度追加で回復するようになり、回復するたびに回復量ボーナス効果から受ける恩恵が$N1%増加します。\n\nさらに、別のプリーストのRenewを受けている対象にもRenewを付与できるようになります。", nil, 0xe14c3cd2, nil, "um" },
  [425310] = { "ベルトにRenewed Hopeのルーンを刻みます：\n\n$I1\nFlash Heal、Binding Heal、Lesser Heal、Heal、Greater Heal、Penanceによる回復は、Weakened Soulを受けている対象に使用するとクリティカル率が$N1%上昇し、その対象のWeakened Soulの残り時間を$D1短縮します。", nil, 0x88a25871, nil, "um" },
  [425312] = { "ブーツにSpirit of the Redeemerのルーンを刻みます：\n\n$I1\n発動すると$D1の間Spirit of Redemptionになります。この姿の間はあらゆる回復呪文をコストなしで詠唱できますが、移動、攻撃はできず、攻撃されることも、呪文や効果の対象になることもありません。発動にはSpirit of Redemptionのタレントが必要で、死亡時にSpirit of Redemptionになることはなくなります。", nil, 0x10efc022, nil, "um" },
  [425314] = { "ブーツにDispersionのルーンを刻みます：\n\n$I1\n純粋なShadowエネルギーへと分散し、受けるダメージをすべて$N1%軽減します。攻撃も呪文の詠唱もできなくなりますが、$D2の間$D1ごとにマナを$N2%回復します。Dispersionはスタン、恐怖、沈黙状態でも使用でき、使用時にすべての鈍足効果と移動妨害効果を解除し、分散中はそれらへの耐性を得ます。", nil, 0x0287aa9b, nil, "um" },
  [425336] = { "$D1の間、攻撃速度を$N1%増加させます。", "攻撃速度が$N1%増加しています。", 0x7e4b2c7f, 0x8859e2db, "uu" },
  [425339] = { "前方の円錐範囲にいる最大$N1体の敵に$N2のFireダメージを与えます。このアビリティは大量の脅威を発生させます。Flame Shockの持続ダメージには、$N3%の確率でMolten Blastのクールダウンをリセットする効果があります。", nil, 0x08546866, nil, "um" },
  [425340] = { "Molten Blastのアビリティを得ます：\n\n$I1\n前方の円錐範囲にいる敵最大$N1体を吹き飛ばし、$N2のFireダメージを与えます。このアビリティは大量の脅威を発生させます。Flame Shockの継続ダメージには、$N3%の確率でMolten Blastのクールダウンをリセットする効果があります。", nil, 0x32a57cd3, nil, "um" },
  [425341] = { "Greater Ghost Wolfのアビリティを得ます：\n\n$I1\nGhost Wolfのアビリティが屋内でも使用できるようになり、有効な間は受けるすべてのダメージが$N1%減少します。", nil, 0xe67819f9, nil, "um" },
  [425343] = { "脚部にGreater Ghost Wolfのルーンを刻みます：\n\n$I1\nGhost Wolfが屋内でも使用できるようになり、発動中は受けるダメージをすべて$N1%軽減します。", nil, 0x0f11028d, nil, "um" },
  [425344] = { "手袋にMolten Blastのルーンを刻みます：\n\n$I1\n前方の円錐範囲内の最大$N1体の敵を爆破し、$N2のFireダメージを与えます。このアビリティは大量の脅威を生み出します。Flame Shockの持続ダメージは、$N3%の確率でMolten Blastのクールダウンをリセットします。", nil, 0x23c7149c, nil, "um" },
  [425412] = { "両手武器を装備している間、攻撃速度が$N2%上昇し、近接攻撃が命中するたびに追加で怒りを$N3、クリティカルヒットの場合は追加で怒りを$N4生み出します。", nil, 0x1e91f2d1, nil, "um" },
  [425415] = { nil, "激怒しています。", nil, 0x8be4b6b8, "mu" },
  [425418] = { "怒りが$N2を超えると、$D1の間Enraged状態になります（Enraged状態が必要なアビリティが使用可能になります）。さらに、Enraged状態の間はWhirlwindがオフハンドの近接武器でも攻撃するようになります。", nil, 0xc054ad73, nil, "um" },
  [425421] = { "Charge、Intercept、Interveneのアビリティが戦闘中やどのスタンスでも使用できるようになり、使用時にすべての移動阻害効果を解除するようになります。", nil, 0xb79da555, nil, "um" },
  [425428] = { "Quick Strikeのアビリティを得ます：\n\n$I1\n両手武器による無謀な即時の近接攻撃で、$N1の物理ダメージを与えます。このアビリティはHeroic Strikeに関連するすべての効果の恩恵を受け、それらを発動させます。", nil, 0x56596499, nil, "um" },
  [425429] = { "Raging Blowのアビリティを得ます：\n\n$I1\n武器ダメージの$N1%を与える猛烈な一撃ですが、Enrage、Berserker Rage、Bloodrageのいずれかが有効な間しか使用できません。Enrage、Berserker Rage、Bloodrageが有効な間に他の近接アビリティを使うたびに、Raging Blowの残りクールダウンが$D1短縮されます。", nil, 0x103bfb7d, nil, "um" },
  [425430] = { "Warbringerのアビリティを得ます：\n\n$I1\nCharge、Intercept、Interveneのアビリティが戦闘中やどのスタンスでも使用できるようになり、使用時にすべての移動阻害効果を解除するようになります。", nil, 0xb338ca67, nil, "um" },
  [425440] = { "Consumed by Rageのアビリティを得ます：\n\n$I1\n怒りが$N2を超えると、$D1の間Enraged状態になります（Enraged状態が必要なアビリティが使用可能になります）。さらに、Enraged状態の間はWhirlwindがオフハンドの近接武器でも攻撃するようになります。", nil, 0x985a7941, nil, "um" },
  [425442] = { "Frenzied Assaultのアビリティを得ます：\n\n$I1\n両手武器を装備している間、攻撃速度が$N2%上昇し、近接攻撃が命中するたびに追加で怒りを$N3、クリティカルヒットの場合は追加で怒りを$N4生み出します。", nil, 0x85410117, nil, "um" },
  [425443] = { "手袋にQuick Strikeのルーンを刻みます：\n\n$I1\n両手武器で無謀な即時近接攻撃を行い、$N1の物理ダメージを与えます。このアビリティはHeroic Strikeに関連するすべての効果の恩恵を受け、それらを発動させます。", nil, 0xfe2ebe8b, nil, "um" },
  [425444] = { "胸部にRaging Blowのルーンを刻みます：\n\n$I1\n武器ダメージの$N1%を与える猛烈な一撃ですが、Enrage、Berserker Rage、Bloodrageのいずれかが有効な間にしか使用できません。Enrage、Berserker Rage、Bloodrageのいずれかが有効な間に他の近接アビリティを使用するたびに、Raging Blowの残りクールダウンが$D1短縮されます。", nil, 0x95af0904, nil, "um" },
  [425445] = { "胸部にWarbringerのルーンを刻みます：\n\n$I1\nCharge、Intercept、Interveneが、戦闘中でもどの構えでも使用できるようになり、発動時にすべての移動妨害効果を解除します。", nil, 0xd9810bbd, nil, "um" },
  [425446] = { "脚部にConsumed by Rageのルーンを刻みます：\n\n$I1\n怒りが$N2を超えると、$D1の間Enrage状態になります（Enraged状態が必要なアビリティが使用可能になります）。さらに、Enraged状態の間はWhirlwindがオフハンドの近接武器でも攻撃します。", nil, 0x002a5c3b, nil, "um" },
  [425447] = { "脚部にFrenzied Assaultのルーンを刻みます：\n\n$I1\n両手武器を装備している間、攻撃速度が$N2%上昇し、近接攻撃が命中すると怒りを追加で$N3生み出します。クリティカルヒットの場合は追加で$N4生み出します。", nil, 0x17dbef85, nil, "um" },
  [425460] = { nil, "夢が崩れつつあります。", nil, 0x2b57184c, "mu" },
  [425463] = { "フェルエネルギーをみなぎらせ、ペットと自分の回避率を$N1%、すべての攻撃のクリティカル率を$N2%上昇させます。効果時間は$D1です。", "回避率が$N1%上昇しています。\n主人のクリティカル率が$N2%上昇しています。", 0x95ecc1be, 0xb041bbc1, "uu" },
  [425464] = { "別の悪魔のペットを召喚しても、Demonic Sacrificeの効果が解除されなくなります。生贄にしたペットを再召喚すると、効果は解除されます。", nil, 0x910d423f, nil, "um" },
  [425467] = { nil, "呪文のダメージと回復量が$N1増加します。", nil, 0x79cd41df, "mu" },
  [425473] = { "Demonic Pactのアビリティを得ます：\n\n$I1\n別のDemonペットを召喚しても、Demonic Sacrificeの効果が解除されなくなります。犠牲にしたペットを再召喚すると、効果は解除されます。", nil, 0x71ac3206, nil, "um" },
  [425474] = { "Demonic Graceのアビリティを得ます：\n\n$I1\n邪悪なエネルギーをみなぎらせ、ペットと自分の回避率を$N1%、すべての攻撃のクリティカル率を$N2%上昇させます。$D1持続します。", nil, 0xa8b370d2, nil, "um" },
  [425476] = { "脚部にDemonic Pactのルーンを刻みます：\n\n$I1\nDemonic Sacrificeの効果が、別の悪魔のペットを召喚しても解除されなくなります。生け贄にしたペットを再召喚すると、効果は解除されます。", nil, 0x15896149, nil, "um" },
  [425477] = { "脚部にDemonic Graceのルーンを刻みます：\n\n$I1\nフェルエネルギーをみなぎらせ、ペットと自分の回避率を$N1%、すべての攻撃のクリティカル率を$N2%上昇させます。効果時間は$D1です。", nil, 0x08b6b628, nil, "um" },
  [425497] = { "餌を投げます。", nil, 0xb670e33c, nil, "um" },
  [425589] = { "ブロック値が$N1%上昇し、Redoubtの才能が変化します。Redoubtは自分への近接攻撃や遠隔攻撃からも$N2%の確率で発動するようになり、近接攻撃でクリティカルを与えると必ず発動します。さらに、Reckoningの才能が、自分への近接攻撃や遠隔攻撃から才能ポイントごとに$N3%の確率で発動するようになります。", nil, 0x62ae9a8a, nil, "um" },
  [425600] = { { "パラディンがHorn of Lordaeronを吹き鳴らし、$N1ヤード以内のパーティーメンバー全員の筋力と敏捷性の合計を$N2上昇させます。効果時間は$D1です。Blessing of Mightとは重複しません。", shape = { "3/1" } }, "筋力と敏捷性の合計が$N1増加します。", 0xc2588b8d, 0x4c95c821, "uu" },
  [425609] = { "呪文の詠唱を中断させ、$D1の間その系統の呪文を唱えられなくします。", nil, 0x25cb829f, nil, "um" },
  [425614] = { "Hallowed Groundのアビリティを得ます：\n\n$I1\nConsecrationが、範囲内のパーティーメンバーをConsecrationのダメージ値の$N1%分回復するようにもなります。", nil, 0xe4cdfe6b, nil, "um" },
  [425615] = { "Aegisのアビリティを得ます：\n\n$I1\nブロック値が$N1%上昇し、Redoubtの才能が変化します。Redoubtは自分への近接攻撃や遠隔攻撃からも$N2%の確率で発動するようになり、近接攻撃でクリティカルを与えると必ず発動します。さらに、Reckoningの才能が、自分への近接攻撃や遠隔攻撃から才能ポイントごとに$N3%の確率で発動するようになります。", nil, 0xb503216f, nil, "um" },
  [425616] = { "Rebukeのアビリティを得ます：\n\n$I1\n詠唱を妨害し、$D1の間その系統の呪文を詠唱できなくします。", nil, 0x06e6051f, nil, "um" },
  [425618] = { "胸部にHallowed Groundのルーンを刻みます：\n\n$I1\nConsecrationが、範囲内のパーティーメンバーをConsecrationのダメージ量の$N1%分回復するようになります。", nil, 0x96d0ec24, nil, "um" },
  [425619] = { "胸部にAegisのルーンを刻みます：\n\n$I1\nブロック値を$N1%上昇させ、Redoubtタレントを変化させます。Redoubtは、自分への近接攻撃または遠隔攻撃を受けた時にも$N2%の確率で発動するようになり、近接クリティカルを与えた時には必ず発動します。さらに、Reckoningタレントは、自分への近接攻撃または遠隔攻撃を受けた時に、タレントポイントごとに$N3%の確率で発動するようになります。", nil, 0x4ecc3126, nil, "um" },
  [425621] = { "脚部にRebukeのルーンを刻みます：\n\n$I1\n呪文の詠唱を中断させ、$D1の間その系統の呪文を詠唱できなくします。", nil, 0x69981c41, nil, "um" },
  [425711] = { "前方のすべての敵を近接武器で薙ぎ払い、武器ダメージの$N1%を与えます。主な対象が受けるダメージは$N2%増加します。", nil, 0x24f251b2, nil, "um" },
  [425713] = { "ShotとStrikeのアビリティ、およびMongoose Biteでクリティカルヒットを与えると、ペットの次の2回の特殊攻撃が必ずクリティカルヒットになります。", nil, 0xc4c6a018, nil, "um" },
  [425714] = { "Shotのアビリティでクリティカルヒットを与えると、ペットの次の2回の特殊攻撃が必ずクリティカルヒットになります。", "ペットの特殊アビリティが必ずクリティカルになります。", 0xfd27a430, 0x1a7c794a, "uu" },
  [425718] = { "Shotのアビリティでクリティカルヒットを与えると、ペットの次の2回の特殊攻撃が必ずクリティカルヒットになります。", "ペットの特殊アビリティが必ずクリティカルになります。", 0xfd27a430, 0x1a7c794a, "uu" },
  [425728] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425729] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425730] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425732] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425733] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425734] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425735] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425736] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425737] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425738] = { "Multi-Shotが命中した対象は、$D1の間Serpent Stingにもかかります。", nil, 0xfd520141, nil, "um" },
  [425754] = { "Carveのアビリティを得ます：\n\n$I1\n前方のすべての敵を近接武器で薙ぎ払い、武器ダメージの$N1%を与えます。主な対象には$N2%増加したダメージを与えます。", nil, 0xc57af772, nil, "um" },
  [425755] = { "Cobra Strikesのアビリティを得ます：\n\n$I1\nShotとStrikeのアビリティ、およびMongoose Biteでクリティカルヒットを与えると、ペットの次の2回の特殊攻撃が必ずクリティカルヒットになります。", nil, 0xc059b510, nil, "um" },
  [425756] = { "Serpent Spreadのアビリティを得ます：\n\n$I1\nMulti-Shotが命中した対象は、$D1の間Serpent Stingにもかかります。", nil, 0x649f5357, nil, "um" },
  [425757] = { "Flanking Strikeのアビリティを得ます：\n\n$I1\n自分とペットが同時に即座に近接ダメージの$N1%を与えます。その後、$D1の間、与えるダメージが$N2%増加します。最大$N4回までスタックします。ペットのBasic攻撃には、$N5%の確率でFlanking Strikeのクールダウンをリセットする効果があります。", nil, 0xb7bf4b06, nil, "um" },
  [425758] = { "手袋にCarveのルーンを刻みます：\n\n$I1\n前方のすべての敵を近接武器でなぎ払い、武器ダメージの$N1%を与えます。主目標が受けるダメージは$N2%増加します。", nil, 0x3c61f546, nil, "um" },
  [425759] = { "胸部か法衣にCobra Strikesのルーンを刻みます：\n\n$I1\nShotとStrikeのアビリティ、およびMongoose Biteでクリティカルヒットを与えると、ペットの次の2回の特殊攻撃が必ずクリティカルヒットになります。", nil, 0xd5359e71, nil, "um" },
  [425760] = { "脚部にSerpent Spreadのルーンを刻みます：\n\n$I1\nMulti-Shotが命中した対象は、$D1の間Serpent Stingにも冒されます。", nil, 0x5f415872, nil, "um" },
  [425762] = { "脚部にFlanking Strikeのルーンを刻みます：\n\n$I1\n自分とペットが同時に即時の近接攻撃を行い、$N1%の近接ダメージを与えます。その後、$D1の間与えるダメージが$N2%増加し、最大$N4回までスタックします。ペットのBasic攻撃は、$N5%の確率でFlanking Strikeのクールダウンをリセットします。", nil, 0x2cd65e38, nil, "um" },
  [425798] = { nil, "このユニットは最近Gurubashi Arenaの宝箱を略奪したため、しばらくの間は再び戦利品を得られません。", nil, 0x78eb8040, "mu" },
  [425858] = { "Healing WaveまたはLesser Healing Waveでクリティカル回復すると、Ancestralの霊を呼び出して助けを得ます。霊は40ヤード以内で体力の割合が最も低いパーティーメンバーを、回復量の$N2%分即座に回復します。", nil, 0xd30bce97, nil, "um" },
  [425864] = { "Healing WaveまたはLesser Healing Waveでクリティカル回復すると、Ancestralの霊を呼び出して助けを得ます。霊は40ヤード以内で体力の割合が最も低い味方のパーティーまたはレイドの対象を即座に回復します。", nil, 0xbc4a8023, nil, "um" },
  [425874] = { "対象の足元に体力 $N2のDecoy Totemを$D1の間召喚し、対象への次の近接攻撃または遠隔攻撃をトーテムにそらします。トーテムは対象に$D2の間、移動阻害効果への耐性も与えます。", nil, 0x4df50519, nil, "um" },
  [425876] = { nil, "近接攻撃または遠隔攻撃を1回、Decoy Totemにそらします。", nil, 0x39a46385, "mu" },
  [425879] = { "Ancestral Awakeningのアビリティを得ます：\n\n$I1\nHealing WaveまたはLesser Healing Waveでクリティカル回復すると、Ancestralの霊を呼び出して助けを得ます。霊は40ヤード以内で体力の割合が最も低いパーティーメンバーを、回復量の$N2%分即座に回復します。", nil, 0x7f9b44ab, nil, "um" },
  [425881] = { "Decoy Totemのアビリティを得ます：\n\n$I1\n体力$N2のDecoy Totemを$D1の間、対象の足元に召喚します。対象に向けられた次の近接攻撃または遠隔攻撃は、代わりにトーテムに向かいます。トーテムは$D2の間、対象に移動阻害効果への耐性も与えます。", nil, 0x9212fa0d, nil, "um" },
  [425882] = { "ブーツにDecoy Totemのルーンを刻みます：\n\n$I1\n対象の足元に、体力が$N2のDecoy Totemを$D1の間召喚します。対象への次の近接攻撃または遠隔攻撃は、代わりにトーテムに向けられます。さらにトーテムは、$D2の間、対象に移動妨害効果への耐性を与えます。", nil, 0x8e83f725, nil, "um" },
  [425883] = { "ブーツにAncestral Awakeningのルーンを刻みます：\n\n$I1\nHealing WaveまたはLesser Healing Waveでクリティカル回復をすると、Ancestralの霊を召喚して助けを得ます。霊は40ヤード以内で体力の割合が最も低いパーティーメンバーを、回復量の$N2%分即座に回復します。", nil, 0x93669494, nil, "um" },
  [425887] = { nil, "あなたの中の何かが、Gnollの血と復讐に飢えています……", nil, 0xc8c5dbf4, "mu" },
  [425891] = { nil, "オープナーが抵抗されました。", nil, 0x0ea6a3e3, "mu" },
  [425893] = { nil, "Wendigoは不潔なことで知られていますが、こいつは特に脂ぎっています。", nil, 0xc50e2d5c, "mu" },
  [425894] = { "$D2の間、$D1ごとに敵に物理ダメージを与えます。", "$D1ごとに$N1の物理ダメージを受けます。", 0x40a759e7, 0x59f89116, "uu" },
  [425895] = { "敵に$N1のFrostダメージを与えます。", "攻撃間隔が$N1%長くなっています\n移動速度が$N2%低下しています。", 0xe9a78e07, 0xc42f1bbc, "uu" },
